package com.example.ems.security;
import com.example.ems.service.*;import com.example.ems.model.SessionUser;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.*;import org.springframework.transaction.annotation.EnableTransactionManagement;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.mock.web.*;import org.springframework.web.context.request.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class Rc2SecurityDatabaseIT {
 static final AtomicBoolean failAudit=new AtomicBoolean();static int count;
 static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);count++;System.out.println("PASS: "+name);}
 static void rejects(Runnable action,String name){boolean rejected=false;try{action.run();}catch(RuntimeException e){rejected=true;}check(rejected,name);}
 @EnableTransactionManagement @Import({SessionService.class,SecurityService.class,SecurityPolicy.class}) static class Config {
  @Bean javax.sql.DataSource dataSource(){String url=System.getenv("EMS_IT_URL");com.example.ems.upgrade.Schema.safeUrl(url);String root=System.getenv("EMS_IT_ROOT");if(root!=null){String mode=System.getenv("EMS_IT_MODE");if(!com.example.ems.config.IsolatedFixture.valid(java.nio.file.Path.of(root),System.getenv("EMS_DEVELOPMENT_TASK_ID")))throw new IllegalArgumentException("Owned security fixture required");var env=new org.springframework.core.env.StandardEnvironment();env.getPropertySources().addFirst(new org.springframework.core.env.MapPropertySource("owned-security",java.util.Map.of("EMS_UPGRADE_ROOT",root,"EMS_UPGRADE_MODE",mode)));com.example.ems.config.UpgradeIsolation.verifyInstallation(env,mode,url);}return new DriverManagerDataSource(url,"ems_app",System.getenv("EMS_DB_PASSWORD"));}
  @Bean JdbcTemplate jdbc(javax.sql.DataSource d){return new JdbcTemplate(d);}
  @Bean PlatformTransactionManager transactionManager(javax.sql.DataSource d){return new DataSourceTransactionManager(d);}
  @Bean LogService logService(JdbcTemplate jdbc){return new LogService(jdbc){public void log(Long a,String b,String c,Long d,String e){super.log(a,b,c,d,e);if(failAudit.get())throw new IllegalStateException("Synthetic audit failure");}};}
 }
 static void bind(Long id,String token){var request=new MockHttpServletRequest();var session=new MockHttpSession();session.setAttribute("user",new SessionUser(id,"test","虚构测试",2,null,""));session.setAttribute(SessionService.TOKEN,token);request.setSession(session);RequestContextHolder.setRequestAttributes(new ServletRequestAttributes(request));}
 static Long target(JdbcTemplate jdbc,String password){jdbc.update("INSERT INTO employee(employee_no,name,identity_number,birth_date,phone,user_type,hire_date,employment_status) VALUES('269991','虚构并发目标','110101199001019951','1990-01-01','13800000551',0,'2020-01-01',1)");Long id=jdbc.queryForObject("SELECT id FROM employee WHERE employee_no='269991'",Long.class);jdbc.update("INSERT INTO user_account(employee_id,password_hash) VALUES(?,?)",id,new BCryptPasswordEncoder().encode(password));return id;}
 public static void main(String[] args)throws Exception{
  try(var ctx=new AnnotationConfigApplicationContext(Config.class)){
   var jdbc=ctx.getBean(JdbcTemplate.class);var sessions=ctx.getBean(SessionService.class);var security=ctx.getBean(SecurityService.class);var tx=new TransactionTemplate(ctx.getBean(PlatformTransactionManager.class));
   String password=System.getenv("EMS_TEST_PASSWORD"),secondary="SecondaryRace9"+password;Long actor=jdbc.queryForObject("SELECT id FROM employee WHERE employee_no='260001'",Long.class),target=target(jdbc,password);String adminToken=sessions.issue(actor,password),old=sessions.issue(target,password);bind(actor,adminToken);
   security.secondary(actor,password,"",secondary);rejects(()->security.secondary(actor,"",secondary,secondary),"Secondary change must invalidate old password by requiring a different new value");check(jdbc.queryForObject("SELECT credential_version FROM secondary_credential WHERE employee_id=?",Long.class,actor)==1L,"Rejected unchanged secondary password preserves credential version");String grant=security.authorize(actor,target,"RESET",secondary);String prior=jdbc.queryForObject("SELECT password_hash FROM user_account WHERE employee_id=?",String.class,target);
   failAudit.set(true);rejects(()->security.forceReset(actor,target,grant),"Audit failure aborts reset transaction");failAudit.set(false);
   check(prior.equals(jdbc.queryForObject("SELECT password_hash FROM user_account WHERE employee_id=?",String.class,target)),"Reset rollback preserves password hash");check(sessions.validate(target,old)==SessionService.Validity.VALID,"Reset rollback preserves old active session");check(jdbc.queryForObject("SELECT COUNT(*) FROM security_grant WHERE token_hash=? AND consumed_at IS NULL",Integer.class,SessionService.digest(grant))==1,"Reset rollback preserves unconsumed grant");
   var pool=Executors.newFixedThreadPool(2);
   try{
    CountDownLatch protectedWrite=new CountDownLatch(1),release=new CountDownLatch(1),attempted=new CountDownLatch(1);
    var write=pool.submit(()->{bind(target,old);try{return tx.execute(s->{sessions.guardPersonal(target);protectedWrite.countDown();try{if(!release.await(15,TimeUnit.SECONDS))throw new IllegalStateException("Gate timeout");}catch(InterruptedException e){throw new IllegalStateException(e);}jdbc.update("INSERT INTO operation_log(operator_id,operation_type,summary) VALUES(?,'RACE_ALLOWED','先取得保护锁的虚构写入')",target);return true;});}finally{RequestContextHolder.resetRequestAttributes();}});
    if(!protectedWrite.await(15,TimeUnit.SECONDS))throw new AssertionError("Protected lock not acquired");
    var reset=pool.submit(()->{bind(actor,adminToken);try{attempted.countDown();return security.forceReset(actor,target,grant);}finally{RequestContextHolder.resetRequestAttributes();}});attempted.await();release.countDown();check(write.get(20,TimeUnit.SECONDS),"Already-locked write commits before reset");String temporary=reset.get(20,TimeUnit.SECONDS);check(sessions.validate(target,old)!=SessionService.Validity.VALID,"Reset revokes old credential after serialized write");
    bind(target,old);rejects(()->tx.execute(s->{sessions.guardPersonal(target);throw new AssertionError("Invalid write must not execute");}),"Superseded session cannot start protected write after reset");
    String temporaryToken=sessions.issue(target,temporary);bind(target,temporaryToken);rejects(()->tx.execute(s->{sessions.guardCurrent(target,0);return true;}),"Restricted temporary session cannot use ordinary service guard");security.temporaryPassword(target,password+"Formal9");check(sessions.validate(target,temporaryToken)!=SessionService.Validity.VALID,"Temporary password completion revokes restricted session");
    bind(actor,adminToken);String duplicate=security.authorize(actor,target,"RESET",secondary);
    var one=pool.submit(()->{bind(actor,adminToken);try{security.forceReset(actor,target,duplicate);return true;}catch(RuntimeException e){return false;}finally{RequestContextHolder.resetRequestAttributes();}});
    var two=pool.submit(()->{bind(actor,adminToken);try{security.forceReset(actor,target,duplicate);return true;}catch(RuntimeException e){return false;}finally{RequestContextHolder.resetRequestAttributes();}});
    check((one.get(20,TimeUnit.SECONDS)?1:0)+(two.get(20,TimeUnit.SECONDS)?1:0)==1,"Concurrent reset consumes sensitive authorization exactly once");
    for(int i=0;i<5;i++)sessions.failedTemporary(target);check("REISSUE".equals(jdbc.queryForObject("SELECT temporary_state FROM account_security WHERE employee_id=?",String.class,target)),"Five wrong temporary attempts require reissue");
    jdbc.update("UPDATE account_security SET frozen=1,freeze_reason='synthetic',temporary_state='NORMAL' WHERE employee_id=?",target);jdbc.update("UPDATE user_account SET locked_until=DATE_ADD(NOW(),INTERVAL 15 MINUTE) WHERE employee_id=?",target);bind(actor,adminToken);String unfreeze=security.authorize(actor,target,"UNFREEZE",secondary);security.unfreeze(actor,target,unfreeze,"虚构核验");check(jdbc.queryForObject("SELECT COUNT(*) FROM user_account WHERE employee_id=? AND locked_until>NOW()",Integer.class,target)==1,"Unfreeze preserves independent temporary login lock");
    String stale=security.authorize(actor,target,"RESET",secondary);security.secondary(actor,"",secondary,secondary+"New9");rejects(()->security.forceReset(actor,target,stale),"Secondary password change invalidates old grant");
    for(int i=0;i<5;i++)rejects(()->security.authorize(actor,target,"RESET","WrongSecondary9"),"Wrong secondary attempt persists");check(jdbc.queryForObject("SELECT COUNT(*) FROM secondary_credential WHERE employee_id=? AND locked_until>NOW()",Integer.class,actor)==1,"Secondary verification throttled after five failures");check(jdbc.queryForObject("SELECT frozen FROM account_security WHERE employee_id=?",Integer.class,actor)==0,"Executive never security-frozen by secondary failures");
   }finally{pool.shutdownNow();RequestContextHolder.resetRequestAttributes();failAudit.set(false);jdbc.update("DELETE FROM security_grant WHERE actor_id=?",actor);jdbc.update("DELETE FROM secondary_credential WHERE employee_id=?",actor);sessions.revoke(actor,adminToken);}
   System.out.println("rc2 transactional security checks passed: "+count);
  }
 }
}
